SELECT ACCOUNT.`CUST_ID`, `FIRST_NAME`, `LAST_NAME`, `BIRTH_DATE`, SUM(`AVAIL_BALANCE`) AS Total FROM ACCOUNT JOIN INDIVIDUAL ON INDIVIDUAL.`CUST_ID` = ACCOUNT.`CUST_ID` GROUP BY `CUST_ID` HAVING Total>5000;
SELECT * FROM (SELECT ACCOUNT.`CUST_ID`, `FIRST_NAME`, `LAST_NAME`, `BIRTH_DATE`, SUM(`AVAIL_BALANCE`) AS Total FROM ACCOUNT JOIN INDIVIDUAL ON INDIVIDUAL.`CUST_ID` = ACCOUNT.`CUST_ID` GROUP BY `CUST_ID`) AS Balance WHERE Total > 5000;